def language(value=None):
    if not value:
        value = locale.getlocale()[0] or 'en'
    candidate = value.lower().replace('_', '-').split('-')[0].split('.')[0]
    return candidate if candidate in LANGUAGES else 'en'


def message(key, lang='en', **values):
    text = MESSAGES[key][LANGUAGES.index(language(lang))]
    return text.format(**values) if values else text


def catalog(lang):
    return {key: message(key, lang) for key in MESSAGES}


def error_message(error, lang='en'):
    text = str(error)
    lang = language(lang)
    if text in MESSAGES:
        return message(text,lang)
    for source, english, chinese in ERRORS:
        if text == source:
            return source if lang == 'ru' else chinese if lang == 'zh' else english
    match = re.fullmatch(r'API: HTTP (\d{3})\. Проверьте параметры и состояние сервера\.', text)
    if match:
        if lang == 'ru':
            return text
        return ('API: HTTP %s. 请检查参数和服务器状态。' if lang == 'zh' else 'API: HTTP %s. Check arguments and server state.') % match[1]
    # Unknown errors must not echo internal paths, keys or upstream bodies.
    if text in {'quotadisable VDS_ID', 'service status|start|stop|restart'}:
        return text
    return message('failed', lang)


def help_text(lang='en'):
    intro = {
        'en': 'Atlant management commands. Names and JSON fields do not change with language.',
        'ru': 'Команды Atlant. Имена команд и JSON-поля не зависят от языка.',
        'zh': 'Atlant 管理命令。命令名称及 JSON 字段不随界面语言变化。',
    }[language(lang)]
    footer = {
        'en': 'Quota: GiB, accepts 0.1 or 0,1; 0 = unlimited. DAYS=0 = no expiry. INDEX starts at 1.\nconfigset changes RAM; configsave persists settings. TLS modes: manual, acme-ip, acme-domain.\nHTTPS certificates are for subscriptions, not REALITY. Backups are created only on explicit request.',
        'ru': 'Лимит в ГиБ: 0.1 или 0,1; 0 — безлимит. DAYS=0 — бессрочно. INDEX начинается с 1.\nconfigset меняет RAM; configsave сохраняет настройки. Режимы TLS: manual, acme-ip, acme-domain.\nHTTPS-сертификаты относятся к подпискам, не REALITY. Копии создаются только по явному запросу.',
        'zh': '限额单位为 GiB，支持 0.1 或 0,1；0 表示无限制。DAYS=0 表示永久。INDEX 从 1 开始。\nconfigset 仅修改内存；configsave 保存设置。TLS 模式：manual、acme-ip、acme-domain。\nHTTPS 证书用于订阅，不用于 REALITY。仅在明确请求时创建备份。',
    }[language(lang)]
    return intro + '\n\n' + COMMANDS + '\n\n' + footer
